css:
.rdr-radio-option {
  /* Scoped Palette */
  --rdr-red: #d00000;
  --rdr-red-dark: #8a0000;
  --rdr-white: #f0f0f0;
  --rdr-grey: #8c8c8c;
  --rdr-black: #080808;

  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  max-width: 22em; /* Converted to em */
  padding: 0.7em 1.1em; /* Converted to em */
  cursor: pointer;
  font-size: 18px; /* Base size for em scaling */
  transition: transform 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  z-index: 1;
}

/* Hide Default Input */
.rdr-radio-option input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

/* --- Background Strip (The "Pause Menu" Highlight) --- */
.rdr-radio-option::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(
    90deg,
    rgba(208, 0, 0, 0.8),
    rgba(138, 0, 0, 0) 90%
  );
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.4s cubic-bezier(0.23, 1, 0.32, 1);
  z-index: -1;
  /* Ragged Edge simulation */
  clip-path: polygon(0 0, 100% 0, 95% 100%, 0% 100%);
  border-left: 0.25em solid var(--rdr-white);
}

/* --- The Marker (Target Lock) --- */
.rdr-radio-marker {
  position: relative;
  width: 1.5em; /* Scalable size */
  height: 1.5em;
  border: 0.12em solid var(--rdr-grey);
  border-radius: 50%;
  margin-right: 1em;
  transition: all 0.3s ease;
  display: flex;
  justify-content: center;
  align-items: center;
  background: rgba(0, 0, 0, 0.3);
  box-sizing: border-box;
}

/* Rotating Lock Ring */
.rdr-radio-marker::after {
  content: "";
  position: absolute;
  top: -0.4em;
  left: -0.4em;
  right: -0.4em;
  bottom: -0.4em;
  border: 0.12em dashed transparent;
  border-radius: 50%;
  transition: all 0.4s ease;
}

/* --- The X Mark (SVG) --- */
.rdr-x-mark {
  width: 200%;
  height: 200%;
  position: absolute;
  pointer-events: none;
  z-index: 10;
}

.rdr-x-path {
  fill: none;
  stroke: var(--rdr-red);
  stroke-width: 8;
  stroke-linecap: round;
  stroke-dasharray: 60;
  stroke-dashoffset: 60;
  filter: drop-shadow(0 0 0.1em rgba(0, 0, 0, 0.5));
  opacity: 0.9;
}

/* --- Text Label --- */
.rdr-label-text {
  color: var(--rdr-grey);
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  font-size: 1.1em;
  transition: all 0.3s ease;
  position: relative;
  /* Vintage print texture */
  filter: contrast(1.2);
}

/* --- Hover Interactions --- */
.rdr-radio-option:hover .rdr-radio-marker {
  border-color: var(--rdr-white);
  transform: scale(1.1);
}

.rdr-radio-option:hover .rdr-label-text {
  color: var(--rdr-white);
  transform: translateX(0.3em);
}

/* --- Checked State --- */

/* 1. Row Highlight */
.rdr-radio-option input:checked + .rdr-radio-marker + .rdr-label-text {
  color: var(--rdr-white);
  text-shadow: 0.1em 0.1em 0px rgba(0, 0, 0, 0.5);
  transform: translateX(0.6em);
}

.rdr-radio-option:has(input:checked)::before {
  transform: scaleX(1);
}

/* 2. Marker Activation */
.rdr-radio-option input:checked + .rdr-radio-marker {
  border-color: var(--rdr-white);
  background: transparent;
  box-shadow: 0 0 0.8em rgba(255, 255, 255, 0.2);
}

/* 3. Lock Ring Animation */
.rdr-radio-option input:checked + .rdr-radio-marker::after {
  border-color: rgba(255, 255, 255, 0.3);
  animation: rdr-lock-on 4s linear infinite;
}

/* 4. Draw the X */
.rdr-radio-option input:checked + .rdr-radio-marker .rdr-x-path {
  animation: rdr-slash 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}
.rdr-radio-option input:checked + .rdr-radio-marker .rdr-x-path.delay {
  animation-delay: 0.1s;
}

/* 5. Particle Explosion (Pseudo-element on marker) */
.rdr-radio-option input:checked + .rdr-radio-marker::before {
  content: "";
  position: absolute;
  width: 0.2em;
  height: 0.2em;
  border-radius: 50%;
  background: var(--rdr-red);
  z-index: -1;
  /* Box Shadow Particles - using ems for scaling */
  box-shadow:
    0 -1em 0 var(--rdr-red),
    1em -0.8em 0 var(--rdr-red),
    1em 0 0 var(--rdr-red),
    -1em 0.5em 0 var(--rdr-red),
    -0.8em -0.8em 0 var(--rdr-red);
  animation: rdr-impact 0.4s ease-out forwards;
}

/* --- Focus Accessibility --- */
.rdr-radio-option input:focus-visible + .rdr-radio-marker {
  outline: 0.12em solid var(--rdr-white);
  outline-offset: 0.25em;
}

/* --- Animations --- */

@keyframes rdr-slash {
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes rdr-lock-on {
  0% {
    transform: rotate(0deg) scale(1);
  }
  5% {
    transform: rotate(45deg) scale(0.9);
  }
  10% {
    transform: rotate(90deg) scale(1);
  }
  100% {
    transform: rotate(90deg) scale(1);
  }
}

@keyframes rdr-impact {
  0% {
    transform: scale(0);
    opacity: 1;
  }
  100% {
    transform: scale(2);
    opacity: 0;
    box-shadow:
      0 -2em 0 transparent,
      2em -1.5em 0 transparent,
      2em 0 0 transparent,
      -2em 1em 0 transparent,
      -1.5em -1.5em 0 transparent;
  }
}
